mapper.select:
        select
        
        from t_flight_info
        where
              1=1
        
            and flgt_flno = #{flgtFlno,jdbcType=VARCHAR}
        
        
            and flgt_airport_code = #{flgtAirportCode,jdbcType=VARCHAR}
        
        
            and flgt_acname = #{flgtAcname,jdbcType=VARCHAR}
        
        
            and flgt_regn = #{flgtRegn,jdbcType=VARCHAR}
        
        
            and flgt_flti = #{flgtFlti,jdbcType=VARCHAR}
        
        
            and flgt_des3c = #{flgtDes3c,jdbcType=VARCHAR}
        
        
            and flgt_desnm = #{flgtDesnm,jdbcType=VARCHAR}
        
        
            and flgt_d_etot = #{flgtDEtot}
        
        
            and flgt_placecode = #{flgtPlacecode,jdbcType=VARCHAR}
        
        
            and is_auto = #{isAuto,jdbcType=INTEGER}
        
        
            and times = #{times,jdbcType=VARCHAR}
        
        
            and is_effective = #{isEffective,jdbcType=INTEGER}
